CREATE DEFINER=`root`@`localhost` FUNCTION `karma_generar_codigo_barras`(p_marca VARCHAR(80), p_tipo VARCHAR(30)) RETURNS varchar(50) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci
    READS SQL DATA
BEGIN
    DECLARE v_prefijo VARCHAR(40);
